`};var Mi={id:"bento",label:"Bento grid",palettes:{dark:{panel:"#20291e",page:"#161f15",surface:"#303d2b",hover:"#415237",text:"#eff5e5",muted:"#b6c8a8",accent:"#c6dfa7",onAccent:"#293d1d",danger:"#ffb2a1"},light:{panel:"#e6e9df",page:"#f8faf3",surface:"#f7f8f2",hover:"#d7dfcb",text:"#253124",muted:"#57634e",accent:"#374f31",onAccent:"#f5f8ef",danger:"#9b3e30"}},styles:`
